using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.AudioToText;
using Microsoft.SemanticKernel.Connectors.AzureOpenAI;
using Xunit;
using Moq;

namespace Microsoft.SemanticKernel.Tests.Connectors.AzureOpenAI.Extensions
{
    public class AzureOpenAIKernelBuilderExtensionsTests
    {
        [Fact]
        public void AddAzureOpenAIAudioToText_Factory_UsesProvidedOpenAIClient()
        {
            // Arrange
            var builder = new KernelBuilderMock();
            var deploymentName = "deployment1";
            var modelId = "model1";
            var serviceId = "service1";

            var openAIClient = new Mock<object>().Object; // Use object as placeholder
            var loggerFactory = new Mock<ILoggerFactory>().Object;

            var serviceProviderMock = new Mock<IServiceProvider>();
            serviceProviderMock.Setup(sp => sp.GetService(typeof(ILoggerFactory))).Returns(loggerFactory);

            // Act
            var factory = AzureOpenAIKernelBuilderExtensions_AddAzureOpenAIAudioToText_Factory(
                deploymentName, openAIClient, modelId, serviceProviderMock.Object);

            // Assert
            Assert.NotNull(factory);
            Assert.IsType<AzureOpenAIAudioToTextService>(factory);
        }

        [Fact]
        public void AddAzureOpenAIAudioToText_Factory_UsesServiceProviderOpenAIClient_WhenNotProvided()
        {
            // Arrange
            var builder = new KernelBuilderMock();
            var deploymentName = "deployment2";
            var modelId = "model2";
            var serviceId = "service2";

            var openAIClient = new Mock<object>().Object; // Use object as placeholder
            var loggerFactory = new Mock<ILoggerFactory>().Object;

            var serviceProviderMock = new Mock<IServiceProvider>();
            serviceProviderMock.Setup(sp => sp.GetService(typeof(AzureOpenAIClient))).Returns(openAIClient);
            serviceProviderMock.Setup(sp => sp.GetService(typeof(ILoggerFactory))).Returns(loggerFactory);

            // Act
            var factory = AzureOpenAIKernelBuilderExtensions_AddAzureOpenAIAudioToText_Factory(
                deploymentName, null, modelId, serviceProviderMock.Object);

            // Assert
            Assert.NotNull(factory);
            Assert.IsType<AzureOpenAIAudioToTextService>(factory);
        }

        // Helper to invoke the factory delegate from AddAzureOpenAIAudioToText
        private static AzureOpenAIAudioToTextService AzureOpenAIKernelBuilderExtensions_AddAzureOpenAIAudioToText_Factory(
            string deploymentName,
            object? openAIClient,
            string? modelId,
            IServiceProvider serviceProvider)
        {
            // This replicates the factory delegate in the extension method
            var client = openAIClient ?? serviceProvider.GetRequiredService<AzureOpenAIClient>();
            var loggerFactory = (ILoggerFactory?)serviceProvider.GetService(typeof(ILoggerFactory));
            return new AzureOpenAIAudioToTextService(deploymentName, client, modelId, loggerFactory);
        }

        // Minimal mock for IKernelBuilder to satisfy compiler
        private class KernelBuilderMock : IKernelBuilder
        {
            public IServiceCollection Services { get; } = new ServiceCollection();
            public IKernelBuilderPlugins Plugins { get; } = new KernelBuilderPluginsMock();
        }

        private class KernelBuilderPluginsMock : IKernelBuilderPlugins
        {
            public IServiceCollection Services { get; } = new ServiceCollection();
        }
    }
}
